#!/usr/bin/env bash
# SCRIPT_JDOC: {"summary":"Compare ZC1 streamed and non-streamed sustained generation with identical model work","kind":"mixed","weight":"heavy","role":"entrypoint"}
set -euo pipefail
root=$(cd "$(dirname "$0")/../../.." && pwd)
campaign="$root/benchmarks/intel-1340p/gemma-zc-speed-20260916"
out="$campaign/stream-overhead"
build="$root/runtime/deployments/gemma-generation-parity-ddb93ad19-7871f502"
runtime="$root/runtime/gemma-vulkan-f32-0bdd7cd8b/runtime"
model="$root/../models/gemma-4-e4b-qat-mtp/gemma-4-E4B_q4_0-it.gguf"
draft="$root/../models/gemma-4-e4b-qat-mtp/gemma-4-E4B-it-qat-assistant-MTP-Q8_0.gguf"
fixture="$campaign/baseline/sustained-chat-512.json"
production=llama-gemma-zero-copy.service
mkdir -p "$out/runs"
export XDG_RUNTIME_DIR=/run/user/$(id -u);export DBUS_SESSION_BUS_ADDRESS=unix:path=$XDG_RUNTIME_DIR/bus
restore(){ local rc=$?;for u in $(systemctl --user list-units --all --plain --no-legend 'gemma-zc-stream-*.service' 2>/dev/null|awk '{print $1}');do systemctl --user stop "$u">/dev/null 2>&1||true;systemctl --user reset-failed "$u">/dev/null 2>&1||true;done;systemctl --user start "$production">/dev/null 2>&1||true;local ok=0;for _ in $(seq 1 180);do if curl -fsS http://127.0.0.1:18094/health>"$out/restored-health.json" 2>/dev/null;then ok=1;break;fi;sleep 1;done;systemctl --user show "$production" -p ActiveState -p SubState -p MainPID -p NRestarts -p MemorySwapCurrent -p MemorySwapPeak>"$out/restored-service.txt" 2>&1||true;[[ $ok == 1 ]]||rc=1;exit "$rc";};trap restore EXIT INT TERM
systemctl --user is-active --quiet "$production";[[ $(systemctl --user show whisper-stt.service -p ActiveState --value) == inactive ]];[[ $(systemctl --user show whisper-stt-diarizer.service -p ActiveState --value) == inactive ]];! pgrep -x diar-server>/dev/null;! pgrep -x whisper-cli>/dev/null;[[ $(awk '/MemAvailable:/{print $2}' /proc/meminfo) -ge 12582912 ]];systemctl --user stop "$production"
printf 'sequence\tarm\tdecode_tps\twall_s\tdrafted\taccepted\tgenerated\tcontent_sha256\tevents\tcontent_events\tmemory_peak\tswap_peak\n'>"$out/results.tsv"
run_one(){ local seq=$1 arm=$2;local port=$((19100+seq));local unit="gemma-zc-stream-${seq}.service";local dir="$out/runs/$(printf '%02d-%s' "$seq" "$arm")";mkdir -p "$dir";systemd-run --user --unit "$unit" --collect -p Type=simple -p TimeoutStopSec=30 -p MemoryMax=16G -p MemorySwapMax=0 -p TasksMax=256 --setenv=LD_LIBRARY_PATH="$build/bin:$runtime" --setenv=GGML_VK_VISIBLE_DEVICES=0 --setenv=GGML_VK_EXPERIMENTAL_ATTN_MODE=f32 "$build/bin/llama-gemma-zero-copy-server" --model "$model" --draft "$draft" --alias gemma-4-e4b-qat-mtp-zero-copy --host 127.0.0.1 --port "$port" --ctx-size 32768 --batch-size 256 --ubatch-size 256 --threads 8 --threads-batch 16 --draft-max 3 --draft-min 1 --threadpools 0 --model-sampling 1 --max-output 2048 > "$dir/systemd-run.txt";local ok=0;for _ in $(seq 1 180);do if curl -fsS "http://127.0.0.1:$port/health">"$dir/health.json" 2>/dev/null;then ok=1;break;fi;sleep 1;done;[[ $ok == 1 ]];if [[ $arm == stream ]];then GEMMA_URL="http://127.0.0.1:$port" GEMMA_REQUEST="$fixture" GEMMA_CONVERSATION="stream-$seq" bun "$campaign/consume-stream.ts">"$dir/response.json";jq -r '.content' "$dir/response.json">"$dir/content.txt";else curl --max-time 180 -fsS "http://127.0.0.1:$port/v1/chat/completions" -H 'Content-Type: application/json' -H "X-Conversation-Id: nonstream-$seq" --data-binary @"$fixture">"$dir/response.json";jq -r '.choices[0].message.content' "$dir/response.json">"$dir/content.txt";fi;sha256sum "$dir/content.txt"|cut -d' ' -f1>"$dir/content-sha256.txt";local z='.zero_copy';[[ $arm == stream ]]||z='.zero_copy';jq -e "$z | .generated_tokens==512 and .drafted==385 and .accepted==382 and .shared_bytes>0 and .copied_bytes==0" "$dir/response.json";systemctl --user show "$unit" -p ActiveState -p SubState -p MainPID -p NRestarts -p MemoryPeak -p MemorySwapPeak>"$dir/service.txt";local swap=$(sed -n 's/^MemorySwapPeak=//p' "$dir/service.txt");[[ $swap == 0 ]];local mem=$(sed -n 's/^MemoryPeak=//p' "$dir/service.txt");local dec=$(jq -r "$z.decode_tps" "$dir/response.json");local wall=$(jq -r "$z.wall_s" "$dir/response.json");local drafted=$(jq -r "$z.drafted" "$dir/response.json");local accepted=$(jq -r "$z.accepted" "$dir/response.json");local gen=$(jq -r "$z.generated_tokens" "$dir/response.json");local hash=$(cat "$dir/content-sha256.txt");local events=0;local ce=0;if [[ $arm == stream ]];then events=$(jq -r .events "$dir/response.json");ce=$(jq -r .content_events "$dir/response.json");fi;printf '%d\t%s\t%.9f\t%.9f\t%d\t%d\t%d\t%s\t%d\t%d\t%s\t%s\n' "$seq" "$arm" "$dec" "$wall" "$drafted" "$accepted" "$gen" "$hash" "$events" "$ce" "$mem" "$swap">>"$out/results.tsv";journalctl --user -u "$unit" --no-pager>"$dir/journal.txt";systemctl --user stop "$unit";systemctl --user reset-failed "$unit">/dev/null 2>&1||true;sleep 2;}
run_one 1 nonstream;run_one 2 stream;run_one 3 stream;run_one 4 nonstream
[[ $(awk -F '\t' 'NR>1{print $8}' "$out/results.tsv"|sort -u|wc -l) == 1 ]]
sha256sum "$out/results.tsv">"$out/SHA256SUMS"
